-- C08 approved NET_SALES incentive contracts; no bank execution or implicit payroll/GST classification.
CREATE SCHEMA incentives;REVOKE ALL ON SCHEMA incentives FROM PUBLIC;GRANT USAGE ON SCHEMA incentives TO htt_app;
CREATE TABLE incentives.programs(company_id uuid NOT NULL REFERENCES core.companies(id),id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('REBATE','COMMISSION')),name text NOT NULL CHECK(length(btrim(name))BETWEEN 1 AND 200),customer_id uuid,user_id uuid REFERENCES identity.users(id),enabled boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES identity.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,id),FOREIGN KEY(company_id,customer_id)REFERENCES crm.customers(company_id,id),CHECK((kind='REBATE'AND customer_id IS NOT NULL AND user_id IS NULL)OR(kind='COMMISSION'AND user_id IS NOT NULL AND customer_id IS NULL)));
CREATE TABLE incentives.policies(company_id uuid NOT NULL,id uuid NOT NULL,program_id uuid NOT NULL,revision bigint NOT NULL,from_date date NOT NULL,to_date date NOT NULL,config jsonb NOT NULL,expense_account_id uuid NOT NULL,liability_account_id uuid NOT NULL,created_by uuid NOT NULL REFERENCES identity.users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,id),UNIQUE(company_id,program_id,revision),FOREIGN KEY(company_id,program_id)REFERENCES incentives.programs(company_id,id),FOREIGN KEY(company_id,expense_account_id)REFERENCES accounting.accounts(company_id,id),FOREIGN KEY(company_id,liability_account_id)REFERENCES accounting.accounts(company_id,id),CHECK(to_date>from_date),CHECK(config->>'basis'='NET_SALES'));
CREATE TABLE incentives.policy_approvals(company_id uuid NOT NULL,policy_id uuid NOT NULL,approved_by uuid NOT NULL REFERENCES identity.users(id),review_reference text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,policy_id),FOREIGN KEY(company_id,policy_id)REFERENCES incentives.policies(company_id,id));
CREATE TABLE incentives.liability_accounts(company_id uuid NOT NULL,account_id uuid NOT NULL,PRIMARY KEY(company_id,account_id),FOREIGN KEY(company_id,account_id)REFERENCES accounting.accounts(company_id,id));
CREATE TABLE incentives.periods(company_id uuid NOT NULL REFERENCES core.companies(id),id uuid NOT NULL,from_date date NOT NULL,to_date date NOT NULL,state text NOT NULL DEFAULT 'OPEN'CHECK(state IN('OPEN','LOCKED')),snapshot jsonb,version bigint NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES identity.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,id),CHECK(to_date>from_date AND to_date-from_date<=366),CHECK((state='LOCKED')=(snapshot IS NOT NULL)));
CREATE TABLE incentives.runs(company_id uuid NOT NULL,id uuid NOT NULL,program_id uuid NOT NULL,period_id uuid NOT NULL,valuation_date date NOT NULL,posting_date date NOT NULL,plan jsonb NOT NULL,source_hash text NOT NULL,reason text NOT NULL,state text NOT NULL DEFAULT 'DRAFT'CHECK(state IN('DRAFT','APPROVED','REJECTED')),version bigint NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES identity.users(id),approved_by uuid REFERENCES identity.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,id),FOREIGN KEY(company_id,id)REFERENCES platform.documents(company_id,id),FOREIGN KEY(company_id,program_id)REFERENCES incentives.programs(company_id,id),FOREIGN KEY(company_id,period_id)REFERENCES incentives.periods(company_id,id),CHECK(posting_date>=valuation_date),CHECK(source_hash=encode(sha256(convert_to(plan::text,'UTF8')),'hex')));
CREATE TABLE incentives.run_events(company_id uuid NOT NULL,run_id uuid NOT NULL,version bigint NOT NULL,action text NOT NULL,actor_id uuid NOT NULL REFERENCES identity.users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,run_id,version),FOREIGN KEY(company_id,run_id)REFERENCES incentives.runs(company_id,id));
CREATE TABLE incentives.claims(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),program_id uuid NOT NULL,policy_id uuid NOT NULL,invoice_id uuid NOT NULL,kind text NOT NULL,beneficiary_id uuid NOT NULL,origin_period_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,id),UNIQUE(company_id,kind,beneficiary_id,invoice_id),FOREIGN KEY(company_id,program_id)REFERENCES incentives.programs(company_id,id),FOREIGN KEY(company_id,policy_id)REFERENCES incentives.policies(company_id,id),FOREIGN KEY(company_id,invoice_id)REFERENCES sales.invoices(company_id,id),FOREIGN KEY(company_id,origin_period_id)REFERENCES incentives.periods(company_id,id));
CREATE TABLE incentives.accruals(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),claim_id uuid NOT NULL,run_id uuid NOT NULL,delta numeric(20,2)NOT NULL,target numeric(20,2)NOT NULL CHECK(target>=0),posting_date date NOT NULL,valuation_date date NOT NULL,source_snapshot jsonb NOT NULL,PRIMARY KEY(company_id,id),UNIQUE(company_id,claim_id,run_id),FOREIGN KEY(company_id,claim_id)REFERENCES incentives.claims(company_id,id),FOREIGN KEY(company_id,run_id)REFERENCES incentives.runs(company_id,id));
CREATE TABLE incentives.settlements(company_id uuid NOT NULL,id uuid NOT NULL,program_id uuid NOT NULL,mode text NOT NULL CHECK(mode IN('CUSTOMER_CREDIT','SUPPLIER_BILL','SUPPLIER_CREDIT','CLEARING','OFFSET')),posting_date date NOT NULL,reference text NOT NULL,reason text NOT NULL,evidence text NOT NULL,net numeric(20,2)NOT NULL,tax numeric(20,2)NOT NULL,underlying_document_id uuid,prior_settlement_id uuid,created_by uuid NOT NULL REFERENCES identity.users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,id),UNIQUE(company_id,reference),FOREIGN KEY(company_id,id)REFERENCES platform.documents(company_id,id),FOREIGN KEY(company_id,program_id)REFERENCES incentives.programs(company_id,id),FOREIGN KEY(company_id,underlying_document_id)REFERENCES platform.documents(company_id,id),FOREIGN KEY(company_id,prior_settlement_id)REFERENCES incentives.settlements(company_id,id));
CREATE TABLE incentives.settlement_lines(company_id uuid NOT NULL,settlement_id uuid NOT NULL,claim_id uuid NOT NULL,amount numeric(20,2)NOT NULL CHECK(amount<>0),PRIMARY KEY(company_id,settlement_id,claim_id),FOREIGN KEY(company_id,settlement_id)REFERENCES incentives.settlements(company_id,id),FOREIGN KEY(company_id,claim_id)REFERENCES incentives.claims(company_id,id));
CREATE TABLE incentives.display_grants(company_id uuid NOT NULL,program_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES identity.users(id),active boolean NOT NULL,version bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,program_id,user_id),FOREIGN KEY(company_id,program_id)REFERENCES incentives.programs(company_id,id));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['programs','policies','policy_approvals','liability_accounts','periods','runs','run_events','claims','accruals','settlements','settlement_lines','display_grants']LOOP EXECUTE format('ALTER TABLE incentives.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE incentives.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_scope ON incentives.%I USING(company_id=core.current_company())WITH CHECK(company_id=core.current_company())',t);IF t IN('programs','periods','runs','display_grants')THEN EXECUTE format('CREATE TRIGGER touch_version BEFORE UPDATE ON incentives.%I FOR EACH ROW EXECUTE FUNCTION core.touch_version()',t);ELSE EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON incentives.%I FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation()',t);END IF;END LOOP;END$$;
CREATE INDEX ON incentives.accruals(company_id,claim_id,posting_date);CREATE INDEX ON incentives.runs(company_id,state,posting_date);CREATE INDEX ON incentives.claims(company_id,program_id,invoice_id);
INSERT INTO identity.permissions(code,description)VALUES('incentives.read','Read company incentive contracts and ledger'),('incentives.manage','Prepare incentive policies and accruals'),('incentives.approve','Independently approve incentive contracts and accruals'),('incentives.settle','Transfer approved incentive balances to controlled settlement documents'),('incentives.self.read','Read own approved incentives and explicitly granted rebates'),('incentives.grants.manage','Maintain explicit customer rebate display grants');
CREATE FUNCTION identity.seed_incentive_roles(c uuid)RETURNS void LANGUAGE sql SET search_path=pg_catalog AS $$INSERT INTO identity.role_permissions(company_id,role_id,permission_code)SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND((r.code IN('ADMIN','FINANCE')AND p.code LIKE'incentives.%')OR(r.code IN('SALES','OFFICE')AND p.code='incentives.self.read'))ON CONFLICT DO NOTHING$$;
DO $$DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_incentive_roles(c);END LOOP;PERFORM set_config('htt.company_id','',true);END$$;
CREATE FUNCTION incentives.require_access(cap text)RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile(cap);IF cap<>'incentives.self.read'THEN PERFORM crm.require_mobile('incentives.read');PERFORM crm.require_mobile('accounting.ledger.read');PERFORM crm.require_mobile('customers.all');END IF;END$$;
CREATE FUNCTION incentives.lock_company()RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('incentives:'||core.current_company()::text,0));END$$;
CREATE FUNCTION incentives.today()RETURNS date LANGUAGE sql STABLE SET search_path=pg_catalog AS $$SELECT(now()AT TIME ZONE timezone)::date FROM core.companies WHERE id=core.current_company()$$;
CREATE FUNCTION incentives.require_open(d date)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN IF d IS NULL OR d>incentives.today()THEN RAISE EXCEPTION 'Use an actual posting date' USING ERRCODE='HR422';END IF;PERFORM accounting.bas_lock(core.current_company(),false);PERFORM 1 FROM accounting.periods WHERE company_id=core.current_company()AND starts_on<=d AND ends_on>d AND state='OPEN'FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Use the next available open accounting period for corrections' USING ERRCODE='HR409';END IF;END$$;
CREATE FUNCTION incentives.program_json(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE p incentives.programs;BEGIN PERFORM incentives.require_access('incentives.read');SELECT*INTO p FROM incentives.programs WHERE company_id=core.current_company()AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Incentive program unavailable' USING ERRCODE='HT404';END IF;RETURN to_jsonb(p)||jsonb_build_object('policies',(SELECT coalesce(jsonb_agg(to_jsonb(v)||jsonb_build_object('approved',a.policy_id IS NOT NULL,'approvedBy',a.approved_by,'reviewReference',a.review_reference)ORDER BY v.revision),'[]')FROM incentives.policies v LEFT JOIN incentives.policy_approvals a ON a.company_id=v.company_id AND a.policy_id=v.id WHERE v.company_id=p.company_id AND v.program_id=p.id));END$$;
CREATE FUNCTION incentives.create_program(p_id uuid,p_kind text,p_name text,p_customer uuid,p_user uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM incentives.require_access('incentives.manage');PERFORM incentives.lock_company();PERFORM incentives.require_access('incentives.manage');IF p_id IS NULL OR p_id='00000000-0000-0000-0000-000000000000'OR p_kind IS NULL OR p_kind NOT IN('REBATE','COMMISSION')OR coalesce(length(btrim(p_name)),0)NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Valid program details required' USING ERRCODE='HR422';END IF;
 IF p_kind='REBATE'THEN IF p_user IS NOT NULL OR p_customer IS NULL OR NOT crm.mobile_customer_visible(p_customer)THEN RAISE EXCEPTION 'Customer rebate scope denied' USING ERRCODE='42501';END IF;ELSE IF p_customer IS NOT NULL OR p_user IS NULL OR NOT crm.member_permission(p_user,'incentives.self.read')THEN RAISE EXCEPTION 'Active company beneficiary required' USING ERRCODE='42501';END IF;END IF;
 INSERT INTO incentives.programs(company_id,id,kind,name,customer_id,user_id,created_by)VALUES(core.current_company(),p_id,p_kind,btrim(p_name),p_customer,p_user,core.current_actor());RETURN incentives.program_json(p_id);END$$;
CREATE FUNCTION incentives.set_program(p_id uuid,p_version bigint,p_enabled boolean)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM incentives.require_access('incentives.manage');PERFORM incentives.lock_company();IF p_enabled AND EXISTS(SELECT 1 FROM incentives.programs p JOIN incentives.policies v ON v.company_id=p.company_id AND v.program_id=p.id JOIN incentives.policy_approvals av ON av.company_id=v.company_id AND av.policy_id=v.id JOIN incentives.programs q ON q.company_id=p.company_id AND q.id<>p.id AND q.kind=p.kind AND coalesce(q.customer_id,q.user_id)=coalesce(p.customer_id,p.user_id)AND q.enabled JOIN incentives.policies w ON w.company_id=q.company_id AND w.program_id=q.id AND w.from_date<v.to_date AND w.to_date>v.from_date JOIN incentives.policy_approvals aw ON aw.company_id=w.company_id AND aw.policy_id=w.id WHERE p.company_id=core.current_company()AND p.id=p_id)THEN RAISE EXCEPTION 'Enabled beneficiary contracts must not overlap' USING ERRCODE='HR409';END IF;UPDATE incentives.programs SET enabled=p_enabled WHERE company_id=core.current_company()AND id=p_id AND version=p_version;IF NOT FOUND THEN RAISE EXCEPTION 'Program version conflict' USING ERRCODE='HR409';END IF;RETURN incentives.program_json(p_id);END$$;
CREATE FUNCTION incentives.validate_policy(p_program uuid,f jsonb)RETURNS void LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$DECLARE p incentives.programs;mode text:=f->>'settlementMode';acct accounting.accounts;supplier crm.suppliers;BEGIN
 SELECT*INTO p FROM incentives.programs WHERE company_id=core.current_company()AND id=p_program;IF NOT FOUND THEN RAISE EXCEPTION 'Program unavailable' USING ERRCODE='HT404';END IF;
 IF jsonb_typeof(f)IS DISTINCT FROM'object'OR octet_length(f::text)>16000 OR coalesce(f->>'basis','')<>'NET_SALES'OR coalesce(f->>'formula','')NOT IN('PERCENT_NET','FIXED_PER_INVOICE','FIXED_PER_BASE_UNIT')OR(f->>'value')IS NULL OR(f->>'value')::numeric<=0 OR(f->>'value')::numeric>1000000 OR(f->>'value')::numeric<>round((f->>'value')::numeric,6)OR f->>'formula'='PERCENT_NET'AND(f->>'value')::numeric>100 OR coalesce(length(btrim(f->>'taxReviewReference')),0)NOT BETWEEN 1 AND 500 OR jsonb_typeof(f->'deductRebates')IS DISTINCT FROM'boolean'OR jsonb_typeof(f->'retroactiveAcknowledged')IS DISTINCT FROM'boolean'OR jsonb_typeof(f->'recoverableGst')IS DISTINCT FROM'boolean' THEN RAISE EXCEPTION 'Approved NET_SALES formula, explicit tax review and basis flags required; cash/margin/tier rules unsupported' USING ERRCODE='HR422';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(f)k WHERE k NOT IN('basis','formula','value','productId','baseUomId','expenseAccountId','liabilityAccountId','settlementMode','supplierId','clearingAccountId','taxCodeId','taxTreatment','taxReviewReference','deductRebates','retroactiveAcknowledged','recoverableGst'))THEN RAISE EXCEPTION 'Unexpected policy field' USING ERRCODE='HR422';END IF;
 IF f->>'formula'='FIXED_PER_BASE_UNIT'AND(f->>'baseUomId')IS NULL OR(f->>'baseUomId')IS NOT NULL AND NOT EXISTS(SELECT 1 FROM catalog.uoms WHERE company_id=p.company_id AND id=(f->>'baseUomId')::uuid)OR(f->>'productId')IS NOT NULL AND NOT EXISTS(SELECT 1 FROM catalog.products WHERE company_id=p.company_id AND id=(f->>'productId')::uuid)THEN RAISE EXCEPTION 'Explicit eligible product/base unit required' USING ERRCODE='HR422';END IF;
 SELECT*INTO acct FROM accounting.accounts WHERE company_id=p.company_id AND id=(f->>'expenseAccountId')::uuid AND active AND control_kind IS NULL AND(kind='EXPENSE'OR p.kind='REBATE'AND kind='REVENUE');IF NOT FOUND THEN RAISE EXCEPTION 'Active non-control charge account required' USING ERRCODE='HR422';END IF;
 SELECT*INTO acct FROM accounting.accounts WHERE company_id=p.company_id AND id=(f->>'liabilityAccountId')::uuid AND active AND kind='LIABILITY'AND control_kind IS NULL;IF NOT FOUND THEN RAISE EXCEPTION 'Dedicated non-control incentive liability required' USING ERRCODE='HR422';END IF;
 IF mode='CUSTOMER_CREDIT'THEN IF p.kind<>'REBATE'OR f->>'taxTreatment'IS DISTINCT FROM'PRICE_REDUCTION'OR(f->>'supplierId')IS NOT NULL OR(f->>'clearingAccountId')IS NOT NULL THEN RAISE EXCEPTION 'Only reviewed price reductions use customer credits' USING ERRCODE='HR422';END IF;
 ELSIF mode='SUPPLIER_BILL'THEN
 SELECT*INTO supplier FROM crm.suppliers WHERE company_id=p.company_id AND id=(f->>'supplierId')::uuid AND status='ACTIVE';IF NOT FOUND OR(f->>'clearingAccountId')IS NOT NULL OR NOT EXISTS(SELECT 1 FROM accounting.tax_codes WHERE company_id=p.company_id AND id=(f->>'taxCodeId')::uuid)OR(p.kind='REBATE'AND(f->>'taxTreatment'IS DISTINCT FROM'CUSTOMER_SUPPLY'OR supplier.party_id IS DISTINCT FROM(SELECT party_id FROM crm.customers WHERE company_id=p.company_id AND id=p.customer_id)))OR(p.kind='COMMISSION'AND f->>'taxTreatment'IS DISTINCT FROM'CONTRACTOR_SERVICE')OR NOT EXISTS(SELECT 1 FROM accounting.accounts WHERE company_id=p.company_id AND id=(f->>'expenseAccountId')::uuid AND kind='EXPENSE')THEN RAISE EXCEPTION 'Reviewed supplier service, tax code and expense account required' USING ERRCODE='HR422';END IF;
 ELSIF mode='CLEARING'THEN IF p.kind<>'COMMISSION'OR f->>'taxTreatment'IS DISTINCT FROM'EXTERNAL_PAYROLL'OR(f->>'supplierId')IS NOT NULL OR(f->>'taxCodeId')IS NOT NULL OR NOT EXISTS(SELECT 1 FROM accounting.accounts WHERE company_id=p.company_id AND id=(f->>'clearingAccountId')::uuid AND active AND kind='LIABILITY'AND control_kind IS NULL AND id<>(f->>'liabilityAccountId')::uuid AND NOT EXISTS(SELECT 1 FROM incentives.liability_accounts WHERE company_id=p.company_id AND account_id=(f->>'clearingAccountId')::uuid))THEN RAISE EXCEPTION 'Reviewed external payroll clearing; no GST or bank/AP execution' USING ERRCODE='HR422';END IF;
 ELSE RAISE EXCEPTION 'Explicit settlement mode required' USING ERRCODE='HR422';END IF;
 IF EXISTS(SELECT 1 FROM incentives.policies v JOIN incentives.policy_approvals a ON a.company_id=v.company_id AND a.policy_id=v.id WHERE v.company_id=p.company_id AND v.program_id=p.id AND v.liability_account_id<>(f->>'liabilityAccountId')::uuid)THEN RAISE EXCEPTION 'Approved program liability account is immutable' USING ERRCODE='HR409';END IF;
END$$;
CREATE FUNCTION incentives.create_policy(p_id uuid,p_program uuid,p_revision bigint,p_from date,p_to date,f jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v bigint;BEGIN PERFORM incentives.require_access('incentives.manage');PERFORM incentives.lock_company();PERFORM incentives.validate_policy(p_program,f);SELECT coalesce(max(revision),0)INTO v FROM incentives.policies WHERE company_id=core.current_company()AND program_id=p_program;IF p_revision IS DISTINCT FROM v OR p_from IS NULL OR p_to IS NULL OR p_from<'0003-01-01'OR p_to<=p_from THEN RAISE EXCEPTION 'Policy revision/date conflict' USING ERRCODE='HR409';END IF;IF p_from<incentives.today()AND(f->>'retroactiveAcknowledged')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'Explicit retrospective contract acknowledgement required' USING ERRCODE='HR422';END IF;
 INSERT INTO incentives.policies(company_id,id,program_id,revision,from_date,to_date,config,expense_account_id,liability_account_id,created_by)VALUES(core.current_company(),p_id,p_program,v+1,p_from,p_to,f,(f->>'expenseAccountId')::uuid,(f->>'liabilityAccountId')::uuid,core.current_actor());RETURN jsonb_build_object('id',p_id,'revision',v+1,'approved',false);END$$;
CREATE FUNCTION incentives.approve_policy(p_id uuid,p_reference text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v incentives.policies;p incentives.programs;BEGIN PERFORM incentives.require_access('incentives.approve');PERFORM incentives.lock_company();SELECT*INTO v FROM incentives.policies WHERE company_id=core.current_company()AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Policy unavailable' USING ERRCODE='HT404';END IF;IF v.created_by=core.current_actor()THEN RAISE EXCEPTION 'Independent policy approver required' USING ERRCODE='42501';END IF;PERFORM incentives.validate_policy(v.program_id,v.config);SELECT*INTO p FROM incentives.programs WHERE company_id=v.company_id AND id=v.program_id;PERFORM accounting.bas_lock(v.company_id,false);PERFORM 1 FROM accounting.accounts WHERE company_id=v.company_id AND id=v.liability_account_id FOR UPDATE;
 IF coalesce(length(btrim(p_reference)),0)NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Approval evidence required' USING ERRCODE='HR422';END IF;
 IF EXISTS(SELECT 1 FROM incentives.policies q JOIN incentives.policy_approvals a ON a.company_id=q.company_id AND a.policy_id=q.id JOIN incentives.programs other ON other.company_id=q.company_id AND other.id=q.program_id WHERE q.company_id=v.company_id AND q.program_id<>v.program_id AND other.kind=p.kind AND coalesce(other.customer_id,other.user_id)=coalesce(p.customer_id,p.user_id)AND q.from_date<v.to_date AND q.to_date>v.from_date AND(other.enabled))THEN RAISE EXCEPTION 'Overlapping beneficiary contracts would double-accrue the same invoice' USING ERRCODE='HR409';END IF;
 IF NOT EXISTS(SELECT 1 FROM incentives.liability_accounts WHERE company_id=v.company_id AND account_id=v.liability_account_id)THEN IF EXISTS(SELECT 1 FROM accounting.journal_lines WHERE company_id=v.company_id AND account_id=v.liability_account_id)THEN RAISE EXCEPTION 'Accrual liability must start with no journal history' USING ERRCODE='HR422';END IF;INSERT INTO incentives.liability_accounts VALUES(v.company_id,v.liability_account_id);END IF;
 INSERT INTO incentives.policy_approvals(company_id,policy_id,approved_by,review_reference)VALUES(v.company_id,v.id,core.current_actor(),btrim(p_reference));RETURN jsonb_build_object('id',v.id,'approved',true);END$$;
CREATE TABLE incentives.period_events(company_id uuid NOT NULL,period_id uuid NOT NULL,version bigint NOT NULL,action text NOT NULL,snapshot jsonb,reference text NOT NULL,actor_id uuid NOT NULL REFERENCES identity.users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,period_id,version),FOREIGN KEY(company_id,period_id)REFERENCES incentives.periods(company_id,id));
ALTER TABLE incentives.period_events ENABLE ROW LEVEL SECURITY;ALTER TABLE incentives.period_events FORCE ROW LEVEL SECURITY;CREATE POLICY company_scope ON incentives.period_events USING(company_id=core.current_company())WITH CHECK(company_id=core.current_company());CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON incentives.period_events FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
CREATE FUNCTION incentives.create_period(p_id uuid,p_from date,p_to date)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM incentives.require_access('incentives.manage');PERFORM incentives.lock_company();IF p_from IS NULL OR p_to IS NULL OR p_from<'0003-01-01'OR p_to<=p_from OR p_to-p_from>366 THEN RAISE EXCEPTION 'Use 1..366 days' USING ERRCODE='HR422';END IF;IF EXISTS(SELECT 1 FROM incentives.periods WHERE company_id=core.current_company()AND from_date<p_to AND to_date>p_from)THEN RAISE EXCEPTION 'Incentive review periods must not overlap' USING ERRCODE='HR409';END IF;INSERT INTO incentives.periods(company_id,id,from_date,to_date,created_by)VALUES(core.current_company(),p_id,p_from,p_to,core.current_actor());RETURN jsonb_build_object('id',p_id,'state','OPEN','version',1);END$$;
CREATE FUNCTION incentives.claim_accrued(p_claim uuid,p_to date DEFAULT NULL)RETURNS numeric LANGUAGE sql STABLE SET search_path=pg_catalog AS $$SELECT coalesce(sum(delta),0)FROM incentives.accruals WHERE company_id=core.current_company()AND claim_id=p_claim AND(p_to IS NULL OR posting_date<p_to)$$;
CREATE FUNCTION incentives.claim_balance(p_claim uuid)RETURNS numeric LANGUAGE sql STABLE SET search_path=pg_catalog AS $$SELECT incentives.claim_accrued(p_claim)-coalesce((SELECT sum(amount)FROM incentives.settlement_lines WHERE company_id=core.current_company()AND claim_id=p_claim),0)$$;
CREATE FUNCTION incentives.build_plan(p_program uuid,p_period uuid,p_valuation date,p_ids uuid[]DEFAULT NULL)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog SET jit=off AS $$DECLARE p incentives.programs;period incentives.periods;i record;v incentives.policies;cl incentives.claims;facts jsonb;eligible jsonb;original_net numeric;original_qty numeric;retained_qty numeric;actual_net numeric;eligible_net numeric;target numeric;prior numeric;lines jsonb:='[]';n int:=0;beneficiary uuid;last_value date;BEGIN
 PERFORM incentives.require_access('incentives.read');SELECT*INTO p FROM incentives.programs WHERE company_id=core.current_company()AND id=p_program;IF NOT FOUND THEN RAISE EXCEPTION 'Program unavailable' USING ERRCODE='HT404';END IF;SELECT*INTO period FROM incentives.periods WHERE company_id=p.company_id AND id=p_period;IF NOT FOUND THEN RAISE EXCEPTION 'Review period unavailable' USING ERRCODE='HT404';END IF;
 IF p_valuation IS NULL OR p_valuation<period.from_date OR p_valuation>incentives.today()OR cardinality(p_ids)>50 THEN RAISE EXCEPTION 'Valid valuation and at most 50 explicit invoices required' USING ERRCODE='HR422';END IF;beneficiary:=coalesce(p.customer_id,p.user_id);
 IF p_ids IS NOT NULL AND EXISTS(SELECT 1 FROM unnest(p_ids)x WHERE NOT EXISTS(SELECT 1 FROM sales.invoices inv JOIN sales.orders o ON o.company_id=inv.company_id AND o.id=inv.order_id JOIN LATERAL(SELECT salesperson_id FROM sales.order_attributions WHERE company_id=o.company_id AND order_id=o.id ORDER BY version DESC LIMIT 1)a ON true WHERE inv.company_id=p.company_id AND inv.id=x AND inv.invoice_date>=period.from_date AND inv.invoice_date<period.to_date AND inv.invoice_date<=p_valuation AND CASE WHEN p.kind='REBATE'THEN inv.customer_id=p.customer_id ELSE a.salesperson_id=p.user_id END))THEN RAISE EXCEPTION 'Invoice selection outside beneficiary/period scope' USING ERRCODE='42501';END IF;
 FOR i IN SELECT inv.id,inv.invoice_date,inv.order_id FROM sales.invoices inv JOIN sales.orders o ON o.company_id=inv.company_id AND o.id=inv.order_id JOIN LATERAL(SELECT salesperson_id FROM sales.order_attributions WHERE company_id=o.company_id AND order_id=o.id ORDER BY version DESC LIMIT 1)a ON true WHERE inv.company_id=p.company_id AND inv.invoice_date>=period.from_date AND inv.invoice_date<period.to_date AND inv.invoice_date<=p_valuation AND(p_ids IS NULL OR inv.id=ANY(p_ids))AND CASE WHEN p.kind='REBATE'THEN inv.customer_id=p.customer_id ELSE a.salesperson_id=p.user_id END ORDER BY inv.id LIMIT 51 LOOP
 n:=n+1;IF n>50 THEN RAISE EXCEPTION 'Select at most 50 invoices per accrual run' USING ERRCODE='HR422';END IF;
 SELECT*INTO cl FROM incentives.claims WHERE company_id=p.company_id AND kind=p.kind AND beneficiary_id=beneficiary AND invoice_id=i.id;
 IF FOUND THEN IF cl.program_id<>p.id THEN CONTINUE;END IF;SELECT*INTO v FROM incentives.policies WHERE company_id=p.company_id AND id=cl.policy_id;ELSE IF NOT p.enabled THEN CONTINUE;END IF;SELECT q.*INTO v FROM incentives.policies q JOIN incentives.policy_approvals a ON a.company_id=q.company_id AND a.policy_id=q.id WHERE q.company_id=p.company_id AND q.program_id=p.id AND q.from_date<=i.invoice_date AND q.to_date>i.invoice_date ORDER BY q.revision DESC LIMIT 1;IF NOT FOUND THEN CONTINUE;END IF;END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(s)ORDER BY s.posting_date,s.fact_id),'[]')INTO facts FROM sales.net_sales_source s WHERE s.company_id=p.company_id AND s.invoice_id=i.id AND s.posting_date<=p_valuation;
 IF jsonb_array_length(facts)>5000 OR octet_length(facts::text)>3000000 THEN RAISE EXCEPTION 'Invoice history too large for one incentive valuation' USING ERRCODE='HR422';END IF;
 -- Validate actual source revenue, including own rebate credits, independently of incentive exclusions.
 IF EXISTS(WITH expected AS(SELECT s.document_id,sum(s.net)n FROM sales.net_sales_source s WHERE s.company_id=p.company_id AND s.invoice_id=i.id AND s.posting_date<=p_valuation GROUP BY s.document_id),actual AS(SELECT b.source_document_id doc,sum(l.credit-l.debit)n FROM accounting.journal_entries j JOIN accounting.posting_batches b ON b.company_id=j.company_id AND b.id=j.posting_batch_id JOIN accounting.journal_lines l ON l.company_id=j.company_id AND l.journal_entry_id=j.id JOIN accounting.accounts a ON a.company_id=l.company_id AND a.id=l.account_id WHERE j.company_id=p.company_id AND j.posting_date<=p_valuation AND a.kind='REVENUE'GROUP BY b.source_document_id)SELECT 1 FROM expected e LEFT JOIN actual a ON a.doc=e.document_id WHERE e.n<>coalesce(a.n,0))THEN RAISE EXCEPTION 'Sales source revenue differs from GL' USING ERRCODE='HR409';END IF;
 SELECT coalesce(jsonb_agg(e ORDER BY e->>'fact_id'),'[]')INTO eligible FROM jsonb_array_elements(facts)e WHERE((v.config->>'productId')IS NULL OR e->>'product_id'=v.config->>'productId')AND((v.config->>'baseUomId')IS NULL OR e->>'base_uom_id'=v.config->>'baseUomId');
 SELECT coalesce(sum((e->>'net')::numeric)FILTER(WHERE e->>'event_type'='INVOICE'),0),coalesce(sum((e->>'base_quantity')::numeric)FILTER(WHERE e->>'event_type'='INVOICE'),0),coalesce(sum((e->>'base_quantity')::numeric),0),coalesce(sum((e->>'net')::numeric),0)INTO original_net,original_qty,retained_qty,actual_net FROM jsonb_array_elements(eligible)e;
 IF original_net<=0 THEN CONTINUE;END IF;
 SELECT greatest(0,coalesce(sum((e->>'net')::numeric),0))INTO eligible_net FROM jsonb_array_elements(eligible)e WHERE NOT((p.kind='REBATE'OR(v.config->>'deductRebates')::boolean=false)AND EXISTS(SELECT 1 FROM incentives.settlements st JOIN incentives.programs sp ON sp.company_id=st.company_id AND sp.id=st.program_id WHERE st.company_id=p.company_id AND sp.kind='REBATE'AND st.mode='CUSTOMER_CREDIT'AND st.underlying_document_id=(e->>'document_id')::uuid));
 eligible_net:=least(eligible_net,round(original_net*greatest(0,retained_qty)/nullif(original_qty,0),2));IF p.kind='REBATE'AND actual_net<=0 THEN eligible_net:=0;END IF;
 target:=round(CASE v.config->>'formula'WHEN'PERCENT_NET'THEN eligible_net*(v.config->>'value')::numeric/100 WHEN'FIXED_PER_INVOICE'THEN(v.config->>'value')::numeric*eligible_net/original_net ELSE original_qty*(v.config->>'value')::numeric*eligible_net/original_net END,2);
 IF target<0 OR target>999999999999999999.99 OR(v.config->>'settlementMode'='CUSTOMER_CREDIT'AND target>=original_net AND target>0)THEN RAISE EXCEPTION 'Unsupported incentive amount/full-value customer price rebate' USING ERRCODE='HR422';END IF;
 prior:=CASE WHEN cl.id IS NULL THEN 0 ELSE incentives.claim_accrued(cl.id)END;SELECT max(valuation_date)INTO last_value FROM incentives.accruals WHERE company_id=p.company_id AND claim_id=cl.id;IF last_value>p_valuation THEN RAISE EXCEPTION 'Valuation cannot move backwards across approved accruals' USING ERRCODE='HR409';END IF;
 lines:=lines||jsonb_build_array(jsonb_build_object('invoiceId',i.id,'orderId',i.order_id,'claimId',cl.id,'policyId',v.id,'policyRevision',v.revision,'originalNet',original_net::text,'sourceFinancialNet',actual_net::text,'eligibleNet',eligible_net::text,'originalBaseQuantity',original_qty::text,'target',target::text,'priorAccrued',prior::text,'delta',(target-prior)::text,'sourceFacts',facts));
 END LOOP;
 IF octet_length(lines::text)>4000000 THEN RAISE EXCEPTION 'Incentive run too large; select fewer invoices' USING ERRCODE='HR422';END IF;
 RETURN jsonb_build_object('schemaVersion',1,'programId',p.id,'periodId',period.id,'kind',p.kind,'beneficiaryId',beneficiary,'valuationDate',p_valuation,'originLocked',period.state='LOCKED','selectionBasis','EXPLICIT_COMMITTED_INVOICE_SET','lines',lines);
END$$;
CREATE FUNCTION incentives.run_json(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM incentives.require_access('incentives.read');IF NOT EXISTS(SELECT 1 FROM incentives.runs WHERE company_id=core.current_company()AND id=p_id)THEN RAISE EXCEPTION 'Run unavailable' USING ERRCODE='HT404';END IF;RETURN(SELECT to_jsonb(r)FROM incentives.runs r WHERE company_id=core.current_company()AND id=p_id);END$$;
CREATE FUNCTION incentives.create_run(p_id uuid,p_program uuid,p_period uuid,p_valuation date,p_posting date,p_reason text,p_ids uuid[]DEFAULT NULL)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE body jsonb;BEGIN PERFORM incentives.require_access('incentives.manage');PERFORM incentives.lock_company();IF p_posting IS NULL OR p_posting<p_valuation OR p_posting>incentives.today()OR coalesce(length(btrim(p_reason)),0)NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Valuation, posting date and review reason required' USING ERRCODE='HR422';END IF;PERFORM incentives.require_open(p_posting);body:=incentives.build_plan(p_program,p_period,p_valuation,p_ids);
 IF(body->>'originLocked')::boolean AND p_posting<(SELECT to_date FROM incentives.periods WHERE company_id=core.current_company()AND id=p_period)THEN RAISE EXCEPTION 'Locked origin corrections must post in a later period' USING ERRCODE='HR409';END IF;
 INSERT INTO platform.documents(company_id,id,document_type,business_date,state,created_by)VALUES(core.current_company(),p_id,'INCENTIVE_ACCRUAL',p_posting,'DRAFT',core.current_actor());INSERT INTO incentives.runs(company_id,id,program_id,period_id,valuation_date,posting_date,plan,source_hash,reason,created_by)VALUES(core.current_company(),p_id,p_program,p_period,p_valuation,p_posting,body,encode(sha256(convert_to(body::text,'UTF8')),'hex'),btrim(p_reason),core.current_actor());INSERT INTO incentives.run_events VALUES(core.current_company(),p_id,1,'CREATED',core.current_actor(),now());RETURN incentives.run_json(p_id);END$$;
CREATE FUNCTION incentives.run_postings(p_id uuid)RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$WITH entries AS(SELECT v.expense_account_id account,a.delta signed FROM incentives.accruals a JOIN incentives.claims c ON c.company_id=a.company_id AND c.id=a.claim_id JOIN incentives.policies v ON v.company_id=c.company_id AND v.id=c.policy_id WHERE a.company_id=core.current_company()AND a.run_id=p_id UNION ALL SELECT v.liability_account_id,-a.delta FROM incentives.accruals a JOIN incentives.claims c ON c.company_id=a.company_id AND c.id=a.claim_id JOIN incentives.policies v ON v.company_id=c.company_id AND v.id=c.policy_id WHERE a.company_id=core.current_company()AND a.run_id=p_id),grouped AS(SELECT account,sum(signed)n FROM entries GROUP BY account HAVING sum(signed)<>0)SELECT coalesce(jsonb_agg(jsonb_build_object('accountId',account,'debit',greatest(n,0),'credit',greatest(-n,0))ORDER BY account),'[]')FROM grouped$$;
CREATE FUNCTION incentives.approve_run(p_id uuid,p_version bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE r incentives.runs;body jsonb;e jsonb;claim uuid;p incentives.programs;posts jsonb;ids uuid[];BEGIN PERFORM incentives.require_access('incentives.approve');PERFORM incentives.lock_company();SELECT*INTO r FROM incentives.runs WHERE company_id=core.current_company()AND id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Run unavailable' USING ERRCODE='HT404';END IF;IF r.version IS DISTINCT FROM p_version OR r.state<>'DRAFT'THEN RAISE EXCEPTION 'Run state/version conflict' USING ERRCODE='HR409';END IF;IF r.created_by=core.current_actor()THEN RAISE EXCEPTION 'Independent accrual approver required' USING ERRCODE='42501';END IF;
 SELECT array_agg((x->>'invoiceId')::uuid ORDER BY x->>'invoiceId')INTO ids FROM jsonb_array_elements(r.plan->'lines')x;
 PERFORM 1 FROM platform.documents WHERE company_id=r.company_id AND id IN(SELECT(inv->>'orderId')::uuid FROM jsonb_array_elements(r.plan->'lines')inv)ORDER BY id FOR UPDATE;PERFORM incentives.require_open(r.posting_date);PERFORM incentives.require_access('incentives.approve');
 body:=incentives.build_plan(r.program_id,r.period_id,r.valuation_date,coalesce(ids,ARRAY[]::uuid[]));
 IF body<>r.plan THEN RAISE EXCEPTION 'Accrual source/policy/prior totals changed; prepare a new run' USING ERRCODE='HR409';END IF;
 IF(body->>'originLocked')::boolean AND r.posting_date<(SELECT to_date FROM incentives.periods WHERE company_id=r.company_id AND id=r.period_id)THEN RAISE EXCEPTION 'Use a later open period for locked-origin correction' USING ERRCODE='HR409';END IF;
 SELECT*INTO p FROM incentives.programs WHERE company_id=r.company_id AND id=r.program_id;
 FOR e IN SELECT x FROM jsonb_array_elements(body->'lines')x WHERE(x->>'delta')::numeric<>0 LOOP
 PERFORM incentives.validate_policy(r.program_id,(SELECT config FROM incentives.policies WHERE company_id=r.company_id AND id=(e->>'policyId')::uuid));claim:=(e->>'claimId')::uuid;
 IF claim IS NULL THEN INSERT INTO incentives.claims(company_id,program_id,policy_id,invoice_id,kind,beneficiary_id,origin_period_id)VALUES(r.company_id,r.program_id,(e->>'policyId')::uuid,(e->>'invoiceId')::uuid,p.kind,coalesce(p.customer_id,p.user_id),r.period_id)RETURNING id INTO claim;END IF;
 INSERT INTO incentives.accruals(company_id,claim_id,run_id,delta,target,posting_date,valuation_date,source_snapshot)VALUES(r.company_id,claim,p_id,(e->>'delta')::numeric,(e->>'target')::numeric,r.posting_date,r.valuation_date,e);
 END LOOP;posts:=incentives.run_postings(p_id);UPDATE platform.documents SET state='CONFIRMED'WHERE company_id=r.company_id AND id=p_id;IF jsonb_array_length(posts)>0 THEN PERFORM accounting.post_journal(p_id,2,'INCENTIVE_ACCRUAL',r.posting_date,'Approved incentive accrual / linked adjustment',posts);END IF;
 INSERT INTO incentives.run_events VALUES(r.company_id,p_id,r.version+1,'APPROVED',core.current_actor(),now());UPDATE incentives.runs SET state='APPROVED',approved_by=core.current_actor()WHERE company_id=r.company_id AND id=p_id;UPDATE platform.documents SET state='POSTED'WHERE company_id=r.company_id AND id=p_id;RETURN incentives.run_json(p_id);
END$$;
CREATE FUNCTION incentives.reject_run(p_id uuid,p_version bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE r incentives.runs;BEGIN PERFORM incentives.require_access('incentives.manage');PERFORM incentives.lock_company();SELECT*INTO r FROM incentives.runs WHERE company_id=core.current_company()AND id=p_id FOR UPDATE;IF r.state<>'DRAFT'OR r.version IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'Run state/version conflict' USING ERRCODE='HR409';END IF;INSERT INTO incentives.run_events VALUES(r.company_id,p_id,r.version+1,'REJECTED',core.current_actor(),now());UPDATE incentives.runs SET state='REJECTED'WHERE company_id=r.company_id AND id=p_id;UPDATE platform.documents SET state='CANCELLED'WHERE company_id=r.company_id AND id=p_id;RETURN incentives.run_json(p_id);END$$;
-- One approved claim is transferred at a time; external tax amounts require explicit evidence.
CREATE FUNCTION incentives.settle(p_id uuid,p_claim uuid,p_net numeric,p_tax numeric,p_date date,p_reference text,p_reason text,p_evidence text,p_items jsonb,p_prior uuid DEFAULT NULL)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE cl incentives.claims;v incentives.policies;p incentives.programs;mode text;doc uuid;posts jsonb;plan jsonb;other uuid;orig incentives.settlements;BEGIN
 PERFORM incentives.require_access('incentives.settle');PERFORM incentives.lock_company();SELECT*INTO cl FROM incentives.claims WHERE company_id=core.current_company()AND id=p_claim;IF NOT FOUND THEN RAISE EXCEPTION 'Claim unavailable' USING ERRCODE='HT404';END IF;
 PERFORM 1 FROM platform.documents WHERE company_id=cl.company_id AND id=(SELECT order_id FROM sales.invoices WHERE company_id=cl.company_id AND id=cl.invoice_id)FOR UPDATE;
 PERFORM incentives.require_open(p_date);PERFORM incentives.require_access('incentives.settle');SELECT*INTO v FROM incentives.policies WHERE company_id=cl.company_id AND id=cl.policy_id;SELECT*INTO p FROM incentives.programs WHERE company_id=cl.company_id AND id=cl.program_id;PERFORM incentives.validate_policy(p.id,v.config);
 IF p_date<(SELECT max(posting_date)FROM incentives.accruals WHERE company_id=cl.company_id AND claim_id=cl.id)OR p_net IS NULL OR p_net=0 OR p_net<>round(p_net,2)OR p_tax IS NULL OR p_tax<>round(p_tax,2)OR sign(p_tax)NOT IN(0,sign(p_net))OR abs(p_net)>abs(incentives.claim_balance(p_claim))OR sign(p_net)<>sign(incentives.claim_balance(p_claim))OR coalesce(length(btrim(p_reference)),0)NOT BETWEEN 1 AND 180 OR coalesce(length(btrim(p_reason)),0)NOT BETWEEN 1 AND 2000 OR coalesce(length(btrim(p_evidence)),0)NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Explicit amount, tax, balance and evidence required' USING ERRCODE='HR422';END IF;
 plan:=incentives.build_plan(cl.program_id,cl.origin_period_id,incentives.today(),ARRAY[cl.invoice_id]);IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(plan->'lines')e WHERE(e->>'invoiceId')::uuid=cl.invoice_id AND(e->>'delta')::numeric=0)THEN RAISE EXCEPTION 'Approve current sales-source adjustment before settlement' USING ERRCODE='HR409';END IF;
 mode:=v.config->>'settlementMode';other:=v.expense_account_id;
 IF mode='CLEARING'THEN IF p_tax<>0 OR p_prior IS NOT NULL OR p_items IS DISTINCT FROM'[]'::jsonb THEN RAISE EXCEPTION 'Clearing is net only, no bank or payroll calculation' USING ERRCODE='HR422';END IF;other:=(v.config->>'clearingAccountId')::uuid;
 ELSIF mode='CUSTOMER_CREDIT'THEN
 IF p_net<=0 OR p_prior IS NOT NULL OR p_date<>incentives.today()OR jsonb_typeof(p_items)<>'array'OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_items)e WHERE NOT EXISTS(SELECT 1 FROM sales.invoice_lines l WHERE l.company_id=cl.company_id AND l.invoice_id=cl.invoice_id AND l.id=(e->>'invoiceLineId')::uuid AND((v.config->>'productId')IS NULL OR EXISTS(SELECT 1 FROM sales.order_lines ol WHERE ol.company_id=l.company_id AND ol.id=l.order_line_id AND ol.product_id=(v.config->>'productId')::uuid))))OR(SELECT sum((e->>'net')::numeric)FROM jsonb_array_elements(p_items)e)IS DISTINCT FROM p_net OR(SELECT sum((e->>'tax')::numeric)FROM jsonb_array_elements(p_items)e)IS DISTINCT FROM p_tax THEN RAISE EXCEPTION 'Explicit matching original invoice credit lines required; negative recoveries must be carried forward' USING ERRCODE='HR422';END IF;
 doc:=sales.post_amount_credit_note(cl.invoice_id,p_reason,p_items);
 ELSIF mode='SUPPLIER_BILL'THEN
 IF p_date<>incentives.today()OR p_items IS DISTINCT FROM'[]'::jsonb THEN RAISE EXCEPTION 'Supplier settlement uses today and policy expense/tax mapping' USING ERRCODE='HR422';END IF;
 IF p_net>0 THEN IF p_prior IS NOT NULL THEN RAISE EXCEPTION 'Unexpected prior settlement' USING ERRCODE='HR422';END IF;doc:=purchase.post_expense_bill((v.config->>'supplierId')::uuid,p_reference,p_date,p_date,p_date,p_evidence,p_date,p_reason,jsonb_build_array(jsonb_build_object('expenseAccountId',v.expense_account_id,'description',p_reason,'net',p_net,'tax',p_tax,'taxCodeId',v.config->>'taxCodeId','recoverableGst',(v.config->>'recoverableGst')::boolean)));
 ELSE SELECT st.*INTO orig FROM incentives.settlements st WHERE st.company_id=cl.company_id AND st.id=p_prior AND st.mode='SUPPLIER_BILL'AND st.program_id=cl.program_id;IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM incentives.settlement_lines WHERE company_id=cl.company_id AND settlement_id=p_prior AND claim_id=p_claim)THEN RAISE EXCEPTION 'Matching original supplier settlement required' USING ERRCODE='HR422';END IF;
 doc:=purchase.post_expense_credit(orig.underlying_document_id,p_reference,p_reason,(SELECT jsonb_agg(jsonb_build_object('billLineId',id,'amount',-p_net-p_tax))FROM purchase.bill_lines WHERE company_id=cl.company_id AND bill_id=orig.underlying_document_id));
 IF NOT EXISTS(SELECT 1 FROM purchase.supplier_credit_notes WHERE company_id=cl.company_id AND id=doc AND net=-p_net AND tax=-p_tax)THEN RAISE EXCEPTION 'Supplier credit tax allocation differs from approved correction' USING ERRCODE='HR409';END IF;mode:='SUPPLIER_CREDIT';END IF;
 ELSE RAISE EXCEPTION 'Unsupported settlement' USING ERRCODE='HR422';END IF;
 INSERT INTO platform.documents(company_id,id,document_type,business_date,state,created_by)VALUES(cl.company_id,p_id,'INCENTIVE_SETTLEMENT',p_date,'CONFIRMED',core.current_actor());
 INSERT INTO incentives.settlements(company_id,id,program_id,mode,posting_date,reference,reason,evidence,net,tax,underlying_document_id,prior_settlement_id,created_by)VALUES(cl.company_id,p_id,cl.program_id,mode,p_date,btrim(p_reference),p_reason,p_evidence,p_net,p_tax,doc,p_prior,core.current_actor());INSERT INTO incentives.settlement_lines VALUES(cl.company_id,p_id,p_claim,p_net);
 posts:=jsonb_build_array(jsonb_build_object('accountId',v.liability_account_id,'debit',greatest(p_net,0),'credit',greatest(-p_net,0)),jsonb_build_object('accountId',other,'debit',greatest(-p_net,0),'credit',greatest(p_net,0)));
 PERFORM accounting.post_journal(p_id,1,'INCENTIVE_SETTLEMENT',p_date,'Transfer incentive liability; underlying document handles GST',posts);UPDATE platform.documents SET state='POSTED'WHERE company_id=cl.company_id AND id=p_id;
 RETURN jsonb_build_object('id',p_id,'mode',mode,'net',p_net,'tax',p_tax,'underlyingDocumentId',doc,'status','TRANSFERRED');END$$;
CREATE FUNCTION incentives.ledger()RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM incentives.require_access('incentives.read');RETURN jsonb_build_object('claims',(SELECT coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('accrued',incentives.claim_accrued(c.id),'balance',incentives.claim_balance(c.id))ORDER BY c.created_at,c.id),'[]')FROM incentives.claims c WHERE company_id=core.current_company()),'settlements',(SELECT coalesce(jsonb_agg(to_jsonb(s)ORDER BY s.created_at,s.id),'[]')FROM incentives.settlements s WHERE company_id=core.current_company()));END$$;
CREATE FUNCTION incentives.personal()RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM incentives.require_access('incentives.self.read');RETURN(SELECT coalesce(jsonb_agg(jsonb_build_object('programId',p.id,'kind',p.kind,'name',p.name,'approvedNet',coalesce((SELECT sum(a.delta)FROM incentives.accruals a JOIN incentives.claims c ON c.company_id=a.company_id AND c.id=a.claim_id WHERE c.company_id=p.company_id AND c.program_id=p.id),0),'balance',coalesce((SELECT sum(incentives.claim_balance(c.id))FROM incentives.claims c WHERE c.company_id=p.company_id AND c.program_id=p.id),0))ORDER BY p.id),'[]')FROM incentives.programs p WHERE company_id=core.current_company()AND((p.kind='COMMISSION'AND p.user_id=core.current_actor())OR(p.kind='REBATE'AND crm.mobile_customer_visible(p.customer_id)AND EXISTS(SELECT 1 FROM incentives.display_grants g WHERE g.company_id=p.company_id AND g.program_id=p.id AND g.user_id=core.current_actor()AND g.active))));END$$;
CREATE FUNCTION incentives.grant_display(p_program uuid,p_user uuid,p_active boolean,p_version bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v bigint;BEGIN PERFORM incentives.require_access('incentives.grants.manage');PERFORM incentives.lock_company();IF NOT EXISTS(SELECT 1 FROM incentives.programs WHERE company_id=core.current_company()AND id=p_program AND kind='REBATE')OR NOT crm.member_permission(p_user,'incentives.self.read')THEN RAISE EXCEPTION 'Active rebate display recipient required' USING ERRCODE='42501';END IF;SELECT version INTO v FROM incentives.display_grants WHERE company_id=core.current_company()AND program_id=p_program AND user_id=p_user;IF coalesce(v,0)IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'Grant version conflict' USING ERRCODE='HR409';END IF;INSERT INTO incentives.display_grants(company_id,program_id,user_id,active)VALUES(core.current_company(),p_program,p_user,p_active)ON CONFLICT(company_id,program_id,user_id)DO UPDATE SET active=excluded.active;RETURN jsonb_build_object('programId',p_program,'userId',p_user,'active',p_active,'version',coalesce(v,0)+1);END$$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA incentives FROM PUBLIC;
REVOKE ALL ON FUNCTION identity.seed_incentive_roles(uuid)FROM PUBLIC;
GRANT EXECUTE ON FUNCTION incentives.require_access(text),incentives.program_json(uuid),incentives.create_program(uuid,text,text,uuid,uuid),incentives.set_program(uuid,bigint,boolean),incentives.create_policy(uuid,uuid,bigint,date,date,jsonb),incentives.approve_policy(uuid,text),incentives.create_period(uuid,date,date),incentives.build_plan(uuid,uuid,date,uuid[]),incentives.run_json(uuid),incentives.create_run(uuid,uuid,uuid,date,date,text,uuid[]),incentives.approve_run(uuid,bigint),incentives.reject_run(uuid,bigint),incentives.settle(uuid,uuid,numeric,numeric,date,text,text,text,jsonb,uuid),incentives.ledger(),incentives.personal(),incentives.grant_display(uuid,uuid,boolean,bigint)TO htt_app;

CREATE FUNCTION incentives.control_balances(p_to date DEFAULT NULL)RETURNS TABLE(account_id uuid,expected numeric,actual numeric)LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 WITH changes AS(SELECT p.liability_account_id account,a.delta amount FROM incentives.accruals a JOIN incentives.claims c ON c.company_id=a.company_id AND c.id=a.claim_id JOIN incentives.policies p ON p.company_id=c.company_id AND p.id=c.policy_id WHERE a.company_id=core.current_company()AND(p_to IS NULL OR a.posting_date<p_to)
 UNION ALL SELECT p.liability_account_id,-l.amount FROM incentives.settlement_lines l JOIN incentives.settlements s ON s.company_id=l.company_id AND s.id=l.settlement_id JOIN incentives.claims c ON c.company_id=l.company_id AND c.id=l.claim_id JOIN incentives.policies p ON p.company_id=c.company_id AND p.id=c.policy_id WHERE l.company_id=core.current_company()AND(p_to IS NULL OR s.posting_date<p_to)),gl AS(SELECT l.account_id,sum(l.credit-l.debit)n FROM accounting.journal_lines l JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id WHERE l.company_id=core.current_company()AND(p_to IS NULL OR j.posting_date<p_to)GROUP BY l.account_id)
 SELECT r.account_id,coalesce((SELECT sum(amount)FROM changes WHERE account=r.account_id),0),coalesce(gl.n,0)FROM incentives.liability_accounts r LEFT JOIN gl ON gl.account_id=r.account_id WHERE r.company_id=core.current_company()$$;
CREATE OR REPLACE FUNCTION incentives.guard_liability()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE kind text;doc uuid;BEGIN
 PERFORM 1 FROM accounting.accounts WHERE company_id=NEW.company_id AND id=NEW.account_id FOR KEY SHARE;
 IF EXISTS(SELECT 1 FROM incentives.liability_accounts WHERE company_id=NEW.company_id AND account_id=NEW.account_id)THEN SELECT b.posting_kind,b.source_document_id INTO kind,doc FROM accounting.journal_entries j JOIN accounting.posting_batches b ON b.company_id=j.company_id AND b.id=j.posting_batch_id WHERE j.company_id=NEW.company_id AND j.id=NEW.journal_entry_id;
 IF NOT(kind='INCENTIVE_ACCRUAL'AND EXISTS(SELECT 1 FROM incentives.runs WHERE company_id=NEW.company_id AND id=doc)OR kind='INCENTIVE_SETTLEMENT'AND EXISTS(SELECT 1 FROM incentives.settlements WHERE company_id=NEW.company_id AND id=doc))THEN RAISE EXCEPTION 'Reserved incentive liability requires a controlled source' USING ERRCODE='23514';END IF;END IF;RETURN NEW;END$$;
CREATE TRIGGER incentive_liability BEFORE INSERT ON accounting.journal_lines FOR EACH ROW EXECUTE FUNCTION incentives.guard_liability();
CREATE FUNCTION incentives.check_control()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF EXISTS(SELECT 1 FROM incentives.control_balances()WHERE expected<>actual)THEN RAISE EXCEPTION 'Incentive subledger and reserved liability differ' USING ERRCODE='23514';END IF;RETURN NULL;END$$;
CREATE CONSTRAINT TRIGGER incentives_control AFTER INSERT ON incentives.accruals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION incentives.check_control();
CREATE CONSTRAINT TRIGGER incentives_control AFTER INSERT ON incentives.settlement_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION incentives.check_control();
CREATE CONSTRAINT TRIGGER incentives_control AFTER INSERT ON accounting.journal_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION incentives.check_control();
CREATE FUNCTION incentives.review_period(p_id uuid,p_version bigint,p_lock boolean,p_reference text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE p incentives.periods;body jsonb;BEGIN PERFORM incentives.require_access('incentives.approve');PERFORM incentives.lock_company();PERFORM accounting.bas_lock(core.current_company(),true);SELECT*INTO p FROM incentives.periods WHERE company_id=core.current_company()AND id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Incentive period unavailable' USING ERRCODE='HT404';END IF;
 IF p.version IS DISTINCT FROM p_version OR(p.state='LOCKED')=p_lock OR coalesce(length(btrim(p_reference)),0)NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Period version/state or review evidence conflict' USING ERRCODE='HR409';END IF;
 IF p_lock THEN IF p.to_date>incentives.today()OR EXISTS(SELECT 1 FROM incentives.runs WHERE company_id=p.company_id AND period_id=p.id AND state='DRAFT'AND EXISTS(SELECT 1 FROM jsonb_array_elements(plan->'lines')e WHERE(e->>'delta')::numeric<>0))OR EXISTS(SELECT 1 FROM incentives.control_balances()WHERE expected<>actual)THEN RAISE EXCEPTION 'Period has not ended, has pending accruals or unreconciled liability' USING ERRCODE='HR409';END IF;body:=incentives.ledger();
 ELSE IF EXISTS(SELECT 1 FROM accounting.periods WHERE company_id=p.company_id AND starts_on<p.to_date AND ends_on>p.from_date AND state='CLOSED')THEN RAISE EXCEPTION 'Reopen accounting period before incentive review period' USING ERRCODE='HR409';END IF;END IF;
 INSERT INTO incentives.period_events VALUES(p.company_id,p_id,p.version+1,CASE WHEN p_lock THEN'LOCK'ELSE'REOPEN'END,body,p_reference,core.current_actor(),now());UPDATE incentives.periods SET state=CASE WHEN p_lock THEN'LOCKED'ELSE'OPEN'END,snapshot=body WHERE company_id=p.company_id AND id=p_id;RETURN jsonb_build_object('id',p_id,'version',p.version+1,'state',CASE WHEN p_lock THEN'LOCKED'ELSE'OPEN'END);END$$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA incentives FROM PUBLIC;
GRANT EXECUTE ON FUNCTION incentives.review_period(uuid,bigint,boolean,text)TO htt_app;

CREATE OR REPLACE FUNCTION accounting.reconciliation_checks()
RETURNS TABLE(check_code text,entity_id uuid,expected numeric,actual numeric,unit text)
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM accounting.require_reconciliation_access();
 RETURN QUERY
 WITH
 stock_deltas AS (
  SELECT b.id AS balance_id,o.quantity AS qty,0::numeric AS val
  FROM inventory.stock_openings o JOIN inventory.stock_balances b ON b.company_id=o.company_id AND b.warehouse_id=o.warehouse_id AND b.product_id=o.product_id WHERE o.company_id=core.current_company()
  UNION ALL SELECT stock_balance_id,0,value FROM inventory.valuation_openings WHERE company_id=core.current_company()
  UNION ALL SELECT stock_balance_id,base_quantity,valuation_amount FROM purchase.receipt_lines WHERE company_id=core.current_company() AND stock_balance_id IS NOT NULL
  UNION ALL SELECT stock_balance_id,-quantity,-cost FROM inventory.stock_movements WHERE company_id=core.current_company()
  UNION ALL SELECT b.id,l.base_quantity,l.cost FROM inventory.sales_return_lines l JOIN inventory.sales_returns r ON r.company_id=l.company_id AND r.id=l.return_id JOIN sales.order_lines ol ON ol.company_id=l.company_id AND ol.id=l.order_line_id JOIN inventory.stock_balances b ON b.company_id=r.company_id AND b.warehouse_id=r.warehouse_id AND b.product_id=ol.product_id WHERE l.company_id=core.current_company()
  UNION ALL SELECT stock_balance_id,-base_quantity,-cost FROM purchase.return_lines WHERE company_id=core.current_company() AND stock_balance_id IS NOT NULL
  UNION ALL SELECT stock_balance_id,quantity_delta,value_delta FROM inventory.operation_lines WHERE company_id=core.current_company()
  UNION ALL SELECT stock_balance_id,-quantity,-cost FROM inventory.transit_transfer_lines WHERE company_id=core.current_company()
  UNION ALL SELECT stock_balance_id,quantity,cost FROM inventory.transit_event_lines WHERE company_id=core.current_company() AND stock_balance_id IS NOT NULL
 UNION ALL SELECT stock_balance_id,0,inventory_delta FROM inventory.purchase_value_adjustments WHERE company_id=core.current_company() AND stock_balance_id IS NOT NULL
 ), stock_totals AS (SELECT balance_id,sum(qty) AS qty,sum(val) AS val FROM stock_deltas GROUP BY balance_id),
 stock AS (
  SELECT b.*,v.value,coalesce(t.qty,0) AS ledger_qty,coalesce(t.val,0) AS ledger_val,
   coalesce((SELECT sum(r.remaining_quantity) FROM inventory.stock_reservations r WHERE r.company_id=b.company_id AND r.stock_balance_id=b.id),0) AS ledger_reserved
  FROM inventory.stock_balances b LEFT JOIN inventory.stock_values v ON v.company_id=b.company_id AND v.stock_balance_id=b.id LEFT JOIN stock_totals t ON t.balance_id=b.id WHERE b.company_id=core.current_company()
 ), gl AS (
  SELECT a.id,a.control_kind,l.party_id,sum(l.debit-l.credit) AS balance
  FROM accounting.journal_lines l JOIN accounting.accounts a ON a.company_id=l.company_id AND a.id=l.account_id WHERE l.company_id=core.current_company() GROUP BY a.id,a.control_kind,l.party_id
 ), ar_lines AS (SELECT id,customer_id,party_id,remaining_gross-net_paid_amount AS balance FROM sales.invoice_line_balances WHERE company_id=core.current_company()
 ), ar_customer AS (SELECT customer_id,sum(balance) AS balance FROM ar_lines GROUP BY customer_id),
 ar_party AS (SELECT party_id,sum(balance) AS balance FROM ar_lines GROUP BY party_id),
 customer_advances AS (
  SELECT a.id,r.customer_id,a.advance_account_id,a.clearing_account_id,a.amount
   -coalesce((SELECT sum(ap.amount) FROM accounting.active_advance_applications ap WHERE ap.company_id=a.company_id AND ap.advance_id=a.id),0)
   -coalesce((SELECT sum(f.amount) FROM accounting.active_customer_refunds f WHERE f.company_id=a.company_id AND f.advance_id=a.id),0) AS balance
  FROM accounting.active_customer_advances a JOIN accounting.active_customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id WHERE a.company_id=core.current_company()
 ), unbilled AS (SELECT customer_id,sum(amount-released_amount) AS balance FROM sales.credit_commitments WHERE company_id=core.current_company() GROUP BY customer_id),
 ap_party AS (SELECT party_id,sum(outstanding_amount-available_credit) AS balance FROM accounting.ap_balances WHERE company_id=core.current_company() GROUP BY party_id),
 transit_accounts AS (
  SELECT transit_account_id AS id FROM inventory.transit_transfers WHERE company_id=core.current_company() AND transit_account_id IS NOT NULL
  UNION SELECT account_id FROM accounting.account_mappings WHERE company_id=core.current_company() AND purpose='INVENTORY_TRANSIT'
 ), advance_accounts AS (
  SELECT advance_account_id AS id FROM customer_advances
  UNION SELECT account_id FROM accounting.account_mappings WHERE company_id=core.current_company() AND purpose='CUSTOMER_ADVANCES'
 ), supplier_advance_accounts AS (
  SELECT account_id AS id FROM accounting.supplier_advances WHERE company_id=core.current_company()
  UNION SELECT account_id FROM accounting.account_mappings WHERE company_id=core.current_company() AND purpose='SUPPLIER_ADVANCES'
 ), return_accounts AS (
  SELECT contra_account_id AS id FROM purchase.return_lines WHERE company_id=core.current_company() AND bill_line_id IS NOT NULL AND contra_account_id IS NOT NULL
  UNION SELECT account_id FROM accounting.account_mappings WHERE company_id=core.current_company() AND purpose='PURCHASE_RETURN_CLEARING'
 ), grni_party AS (
  SELECT g.party_id,sum(g.amount
   -coalesce((SELECT sum(b.grni_amount) FROM purchase.bill_lines b WHERE b.company_id=g.company_id AND b.grni_item_id=g.id),0)
   -coalesce((SELECT sum(r.valuation_amount) FROM purchase.return_lines r WHERE r.company_id=g.company_id AND r.receipt_line_id=g.receipt_line_id AND r.bill_line_id IS NULL),0)) AS balance
  FROM accounting.grni_items g WHERE g.company_id=core.current_company() GROUP BY g.party_id
 ), checks AS (
  SELECT 'stock.quantity'::text AS code,s.id AS entity,s.ledger_qty AS e,s.on_hand AS a,'BASE_QUANTITY'::text AS u FROM stock s
  UNION ALL SELECT 'stock.value',s.id,s.ledger_val,coalesce(s.value,0),'AUD' FROM stock s
  UNION ALL SELECT 'stock.valuation_missing',s.id,1,CASE WHEN s.value IS NULL THEN 0 ELSE 1 END,'COUNT' FROM stock s WHERE s.on_hand>0
  UNION ALL SELECT 'stock.reserved',s.id,s.ledger_reserved,s.reserved,'BASE_QUANTITY' FROM stock s
  UNION ALL SELECT 'reservation.consumed',r.id,coalesce((SELECT sum(m.quantity) FROM inventory.stock_movements m JOIN inventory.pick_lines pl ON pl.company_id=m.company_id AND pl.id=m.pick_line_id WHERE pl.company_id=r.company_id AND pl.order_line_id=r.order_line_id),0),r.consumed_quantity,'BASE_QUANTITY' FROM inventory.stock_reservations r WHERE r.company_id=core.current_company()
  UNION ALL SELECT 'credit.receivable',c.id,coalesce(a.balance,0),coalesce(x.receivable,0),'AUD' FROM crm.customers c LEFT JOIN ar_customer a ON a.customer_id=c.id LEFT JOIN crm.customer_credit_exposures x ON x.company_id=c.company_id AND x.customer_id=c.id WHERE c.company_id=core.current_company()
  UNION ALL SELECT 'credit.unbilled',c.id,coalesce(b.balance,0),coalesce(x.unbilled_orders,0),'AUD' FROM crm.customers c LEFT JOIN unbilled b ON b.customer_id=c.id LEFT JOIN crm.customer_credit_exposures x ON x.company_id=c.company_id AND x.customer_id=c.id WHERE c.company_id=core.current_company()
  UNION ALL SELECT 'credit.advances',c.id,coalesce((SELECT sum(balance) FROM customer_advances ad WHERE ad.customer_id=c.id),0),coalesce(x.available_advances,0),'AUD' FROM crm.customers c LEFT JOIN crm.customer_credit_exposures x ON x.company_id=c.company_id AND x.customer_id=c.id WHERE c.company_id=core.current_company()
  UNION ALL SELECT 'credit.projection_missing',c.id,1,CASE WHEN x.id IS NULL THEN 0 ELSE 1 END,'COUNT' FROM crm.customers c LEFT JOIN crm.customer_credit_exposures x ON x.company_id=c.company_id AND x.customer_id=c.id WHERE c.company_id=core.current_company()
  UNION ALL SELECT 'credit.commitment',co.id,CASE WHEN d.state='CANCELLED' THEN 0 ELSE o.gross-coalesce((SELECT sum(i.gross) FROM sales.invoices i WHERE i.company_id=co.company_id AND i.order_id=o.id),0)-coalesce((SELECT sum(r.cancelled_gross) FROM inventory.sales_return_lines r JOIN sales.order_lines ol ON ol.company_id=r.company_id AND ol.id=r.order_line_id WHERE ol.company_id=co.company_id AND ol.order_id=o.id AND r.invoice_line_id IS NULL),0) END,co.amount-co.released_amount,'AUD' FROM sales.credit_commitments co JOIN sales.orders o ON o.company_id=co.company_id AND o.id=co.order_id JOIN platform.documents d ON d.company_id=o.company_id AND d.id=o.id WHERE co.company_id=core.current_company()
  UNION ALL SELECT 'invoice.lines',i.id,i.gross,coalesce((SELECT sum(l.gross) FROM sales.invoice_lines l WHERE l.company_id=i.company_id AND l.invoice_id=i.id),0),'AUD' FROM sales.invoices i WHERE i.company_id=core.current_company()
  UNION ALL SELECT 'invoice.receivable',i.id,i.gross,coalesce(r.amount,0),'AUD' FROM sales.invoices i LEFT JOIN accounting.receivable_items r ON r.company_id=i.company_id AND r.invoice_id=i.id WHERE i.company_id=core.current_company()
  UNION ALL SELECT 'invoice.receivable_missing',i.id,1,CASE WHEN r.id IS NULL THEN 0 ELSE 1 END,'COUNT' FROM sales.invoices i LEFT JOIN accounting.receivable_items r ON r.company_id=i.company_id AND r.invoice_id=i.id WHERE i.company_id=core.current_company()
  UNION ALL SELECT 'bill.lines',b.id,b.gross,coalesce((SELECT sum(l.net+l.tax) FROM purchase.bill_lines l WHERE l.company_id=b.company_id AND l.bill_id=b.id),0),'AUD' FROM purchase.bills b WHERE b.company_id=core.current_company()
  UNION ALL SELECT 'bill.payable',b.id,b.gross,coalesce(a.amount,0),'AUD' FROM purchase.bills b LEFT JOIN accounting.ap_items a ON a.company_id=b.company_id AND a.bill_id=b.id WHERE b.company_id=core.current_company()
  UNION ALL SELECT 'bill.payable_missing',b.id,1,CASE WHEN a.id IS NULL THEN 0 ELSE 1 END,'COUNT' FROM purchase.bills b LEFT JOIN accounting.ap_items a ON a.company_id=b.company_id AND a.bill_id=b.id WHERE b.company_id=core.current_company()
  UNION ALL SELECT 'gl.inventory',core.current_company(),coalesce((SELECT sum(value) FROM stock),0)+coalesce((SELECT sum(remaining_cost) FROM inventory.transit_line_balances WHERE company_id=core.current_company()),0),coalesce((SELECT sum(balance) FROM gl WHERE control_kind='INVENTORY'),0),'AUD'
  UNION ALL SELECT 'gl.transit',ta.id,coalesce((SELECT sum(b.remaining_cost) FROM inventory.transit_line_balances b JOIN inventory.transit_transfers t ON t.company_id=b.company_id AND t.id=b.transfer_id WHERE b.company_id=core.current_company() AND t.transit_account_id=ta.id),0),coalesce((SELECT sum(balance) FROM gl WHERE id=ta.id),0),'AUD' FROM transit_accounts ta
  UNION ALL SELECT 'gl.receivable',p.id,coalesce(a.balance,0),coalesce((SELECT sum(balance) FROM gl WHERE control_kind='AR' AND party_id=p.id),0),'AUD' FROM crm.parties p LEFT JOIN ar_party a ON a.party_id=p.id WHERE p.company_id=core.current_company()
  UNION ALL SELECT 'gl.receivable_unassigned',core.current_company(),0,coalesce((SELECT sum(balance) FROM gl WHERE control_kind='AR' AND party_id IS NULL),0),'AUD'
  UNION ALL SELECT 'gl.payable',p.id,coalesce(a.balance,0),-coalesce((SELECT sum(balance) FROM gl WHERE control_kind='AP' AND party_id=p.id),0),'AUD' FROM crm.parties p LEFT JOIN ap_party a ON a.party_id=p.id WHERE p.company_id=core.current_company()
  UNION ALL SELECT 'gl.payable_unassigned',core.current_company(),0,coalesce((SELECT sum(balance) FROM gl WHERE control_kind='AP' AND party_id IS NULL),0),'AUD'
  UNION ALL SELECT 'gl.grni',p.id,coalesce(g.balance,0),-coalesce((SELECT sum(balance) FROM gl WHERE control_kind='GRNI' AND party_id=p.id),0),'AUD' FROM crm.parties p LEFT JOIN grni_party g ON g.party_id=p.id WHERE p.company_id=core.current_company()
  UNION ALL SELECT 'gl.grni_unassigned',core.current_company(),0,coalesce((SELECT sum(balance) FROM gl WHERE control_kind='GRNI' AND party_id IS NULL),0),'AUD'
  UNION ALL SELECT 'gl.customer_advances',aa.id,coalesce((SELECT sum(balance) FROM customer_advances WHERE advance_account_id=aa.id),0),-coalesce((SELECT sum(balance) FROM gl WHERE id=aa.id),0),'AUD' FROM advance_accounts aa
  UNION ALL SELECT 'gl.supplier_advances',aa.id,coalesce((SELECT sum(available) FROM accounting.supplier_advance_balances WHERE company_id=core.current_company() AND account_id=aa.id),0),coalesce((SELECT sum(balance) FROM gl WHERE id=aa.id),0),'AUD' FROM supplier_advance_accounts aa
  UNION ALL SELECT 'gl.purchase_return_clearing',ra.id,coalesce((SELECT sum(r.valuation_amount-coalesce((SELECT sum(cl.net+cl.tax-cl.recoverable_tax+cl.clearing_adjustment) FROM purchase.supplier_credit_lines cl WHERE cl.company_id=r.company_id AND cl.return_line_id=r.id),0)) FROM purchase.return_lines r WHERE r.company_id=core.current_company() AND r.bill_line_id IS NOT NULL AND r.contra_account_id=ra.id),0),coalesce((SELECT sum(balance) FROM gl WHERE id=ra.id),0),'AUD' FROM return_accounts ra
  UNION ALL SELECT 'journal.balance',j.id,0,coalesce(sum(l.debit-l.credit),0),'AUD' FROM accounting.journal_entries j LEFT JOIN accounting.journal_lines l ON l.company_id=j.company_id AND l.journal_entry_id=j.id WHERE j.company_id=core.current_company() GROUP BY j.id
  UNION ALL SELECT 'journal.lines',j.id,1,CASE WHEN count(l.id)>=2 THEN 1 ELSE 0 END,'COUNT' FROM accounting.journal_entries j LEFT JOIN accounting.journal_lines l ON l.company_id=j.company_id AND l.journal_entry_id=j.id WHERE j.company_id=core.current_company() GROUP BY j.id
  UNION ALL SELECT 'journal.batch_entry',b.id,1,count(j.id)::numeric,'COUNT' FROM accounting.posting_batches b LEFT JOIN accounting.journal_entries j ON j.company_id=b.company_id AND j.posting_batch_id=b.id WHERE b.company_id=core.current_company() GROUP BY b.id

  UNION ALL SELECT 'credit_application.total',a.id,a.amount,coalesce((SELECT sum(amount) FROM purchase.credit_application_lines WHERE company_id=a.company_id AND application_id=a.id),0),'AUD' FROM purchase.credit_applications a WHERE a.company_id=core.current_company()
  UNION ALL SELECT 'credit_unapplication.total',u.id,a.amount,u.amount,'AUD' FROM purchase.credit_unapplications u JOIN purchase.credit_applications a ON a.company_id=u.company_id AND a.id=u.application_id WHERE u.company_id=core.current_company()
  UNION ALL SELECT 'credit_application.capacity',cl.id,0,greatest(0,-cl.unallocated_amount),'AUD' FROM purchase.supplier_credit_line_balances cl WHERE cl.company_id=core.current_company()
  UNION ALL SELECT 'credit_application.funds',b.id,0,greatest(0,-b.net_paid_amount),'AUD' FROM purchase.bill_line_balances b WHERE b.company_id=core.current_company() AND EXISTS(SELECT 1 FROM purchase.credit_application_lines l WHERE l.company_id=b.company_id AND b.id IN(l.source_bill_line_id,l.target_bill_line_id))

  UNION ALL SELECT 'customer_credit_application.total',a.id,a.amount,coalesce((SELECT sum(amount) FROM sales.credit_application_lines WHERE company_id=a.company_id AND application_id=a.id),0),'AUD' FROM sales.credit_applications a WHERE a.company_id=core.current_company()
  UNION ALL SELECT 'customer_credit_unapplication.total',u.id,a.amount,u.amount,'AUD' FROM sales.credit_unapplications u JOIN sales.credit_applications a ON a.company_id=u.company_id AND a.id=u.application_id WHERE u.company_id=core.current_company()
  UNION ALL SELECT 'customer_credit_application.capacity',cl.id,0,greatest(0,-cl.unallocated_amount),'AUD' FROM sales.customer_credit_line_balances cl WHERE cl.company_id=core.current_company()
  UNION ALL SELECT 'customer_credit_application.funds',b.id,0,greatest(0,-b.net_paid_amount),'AUD' FROM sales.invoice_line_balances b WHERE b.company_id=core.current_company() AND EXISTS(SELECT 1 FROM sales.credit_application_lines l WHERE l.company_id=b.company_id AND b.id IN(l.source_invoice_line_id,l.target_invoice_line_id))

  UNION ALL SELECT 'receipt_reversal.amount',x.id,r.amount,x.amount,'AUD' FROM accounting.receipt_reversals x JOIN accounting.customer_receipts r ON r.company_id=x.company_id AND r.id=x.receipt_id WHERE x.company_id=core.current_company()
  UNION ALL SELECT 'advance_unapplication.amount',x.id,a.amount,x.amount,'AUD' FROM accounting.advance_unapplications x JOIN accounting.advance_applications a ON a.company_id=x.company_id AND a.id=x.application_id WHERE x.company_id=core.current_company()
  UNION ALL SELECT 'settlement.negative_funds',b.id,0,greatest(0,-b.net_paid_amount),'AUD' FROM sales.invoice_line_balances b WHERE b.company_id=core.current_company()
  UNION ALL SELECT 'advance.negative_available',b.id,0,greatest(0,-b.available),'AUD' FROM accounting.customer_advance_balances b WHERE b.company_id=core.current_company()

  UNION ALL SELECT 'supplier_payment_reversal.amount',r.id,p.amount,r.amount,'AUD' FROM accounting.supplier_payment_reversals r JOIN accounting.supplier_payments p ON p.company_id=r.company_id AND p.id=r.payment_id WHERE r.company_id=core.current_company()
  UNION ALL SELECT 'supplier_advance_unapplication.amount',u.id,a.amount,u.amount,'AUD' FROM accounting.supplier_advance_unapplications u JOIN accounting.supplier_advance_applications a ON a.company_id=u.company_id AND a.id=u.application_id WHERE u.company_id=core.current_company()
  UNION ALL SELECT 'supplier_settlement.negative_funds',b.id,0,greatest(0,-b.net_paid_amount),'AUD' FROM purchase.bill_line_balances b WHERE b.company_id=core.current_company()
  UNION ALL SELECT 'supplier_advance.negative_available',a.id,0,greatest(0,-a.available),'AUD' FROM accounting.supplier_advance_balances a WHERE a.company_id=core.current_company()

  UNION ALL SELECT 'customer_refund_reversal.amount',v.id,r.amount,v.amount,'AUD' FROM accounting.customer_refund_reversals v JOIN accounting.customer_refunds r ON r.company_id=v.company_id AND r.id=v.refund_id WHERE v.company_id=core.current_company()

  UNION ALL SELECT 'supplier_refund_reversal.amount',v.id,r.amount,v.amount,'AUD' FROM accounting.supplier_refund_reversals v JOIN accounting.supplier_refunds r ON r.company_id=v.company_id AND r.id=v.refund_id WHERE v.company_id=core.current_company()

 UNION ALL SELECT 'stock.position_quantity',b.id,b.on_hand,coalesce((SELECT sum(quantity) FROM inventory.positions WHERE company_id=b.company_id AND stock_balance_id=b.id),0),'BASE_QUANTITY' FROM inventory.stock_balances b WHERE b.company_id=core.current_company()
 UNION ALL SELECT 'stock.position_ledger',p.id,p.quantity,coalesce((SELECT sum(quantity) FROM inventory.position_movements WHERE company_id=p.company_id AND position_id=p.id),0),'BASE_QUANTITY' FROM inventory.positions p WHERE p.company_id=core.current_company()
 ) SELECT code,entity,e,a,u FROM checks;
 RETURN QUERY SELECT 'GENERAL_BANK_SOURCE'::text,source_id,0::numeric,difference,'AUD'::text FROM accounting.bank_transaction_gl_differences WHERE company_id=core.current_company();
RETURN QUERY SELECT 'INCENTIVE_LIABILITY'::text,b.account_id,b.expected,b.actual,'AUD'::text FROM incentives.reconciliation_controls()b;END $$;
CREATE FUNCTION incentives.reconciliation_controls()RETURNS TABLE(account_id uuid,expected numeric,actual numeric)LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM accounting.require_reconciliation_access();RETURN QUERY SELECT * FROM incentives.control_balances();END$$;
REVOKE ALL ON FUNCTION incentives.reconciliation_controls()FROM PUBLIC;GRANT EXECUTE ON FUNCTION incentives.reconciliation_controls()TO htt_app;

CREATE OR REPLACE FUNCTION accounting.period_preflight(p_id uuid,p_bas_na boolean DEFAULT false)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog SET jit=off AS $$
 DECLARE c uuid:=core.current_company();p accounting.periods;y accounting.fiscal_years;f jsonb;issues jsonb:='[]';live jsonb;bas jsonb;covered int;required boolean;activity boolean;bad int;today date;BEGIN
 PERFORM accounting.require_close_access('accounting.periods.read');SELECT*INTO p FROM accounting.periods WHERE company_id=c AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Accounting period unavailable' USING ERRCODE='HT404';END IF;SELECT*INTO y FROM accounting.fiscal_years WHERE company_id=c AND id=p.fiscal_year_id;
 SELECT (now()AT TIME ZONE timezone)::date,gst_registered INTO today,required FROM core.companies WHERE id=c;
 IF p.ends_on>today THEN issues:=issues||jsonb_build_array('PERIOD_NOT_ENDED');END IF;
 IF p.starts_on<y.starts_on OR p.ends_on>y.ends_on OR EXISTS(SELECT 1 FROM accounting.periods q WHERE q.company_id=c AND q.id<>p.id AND q.starts_on<p.ends_on AND q.ends_on>p.starts_on)THEN issues:=issues||jsonb_build_array('INVALID_ACCOUNTING_CALENDAR');END IF;
 IF EXISTS(SELECT 1 FROM accounting.periods WHERE company_id=c AND starts_on<p.starts_on AND state<>'CLOSED')THEN issues:=issues||jsonb_build_array('EARLIER_PERIODS_OPEN');END IF;
 IF EXISTS(SELECT 1 FROM accounting.fiscal_year_controls WHERE company_id=c AND id=p.fiscal_year_id AND state='CLOSED')THEN issues:=issues||jsonb_build_array('FISCAL_YEAR_CLOSED');END IF;
 f:=accounting.close_financials(p.starts_on,p.ends_on);
 SELECT coalesce(jsonb_agg(jsonb_build_object('code',check_code,'entityId',entity_id,'expected',expected::text,'actual',actual::text,'unit',unit)ORDER BY check_code,entity_id),'[]'::jsonb)INTO live FROM accounting.reconciliation_checks()WHERE expected IS DISTINCT FROM actual;
 IF jsonb_array_length(live)>0 THEN issues:=issues||jsonb_build_array('CURRENT_SUBLEDGER_INCONSISTENT');END IF;
 IF(f->>'inventoryDifference')::numeric<>0 OR(f->>'settlementErrorCount')::int>0 OR(f->>'trialBalanceDifference')::numeric<>0 OR(f->'gst'->>'glErrorCount')::int+(f->'gst'->>'roleErrorCount')::int+(f->'gst'->>'missingAccountCount')::int>0 OR(f->'gst'->>'labelDifference')::numeric<>0 THEN issues:=issues||jsonb_build_array('HISTORICAL_LEDGERS_UNRECONCILED');END IF;
 SELECT coalesce(sum(least(b.to_date,p.ends_on)-greatest(b.from_date,p.starts_on)),0),coalesce(jsonb_agg(jsonb_build_object('id',b.id,'from',b.from_date,'to',b.to_date,'state',k.state,'reportingMethod',b.reporting_method,'calculationMethod',b.calculation_method,'snapshotId',k.current_snapshot_id)ORDER BY b.from_date),'[]'::jsonb),count(*)FILTER(WHERE b.to_date<=p.ends_on AND k.state='OPEN')INTO covered,bas,bad FROM accounting.bas_effective_periods b JOIN accounting.bas_period_controls k ON k.company_id=b.company_id AND k.id=b.id WHERE b.company_id=c AND b.from_date<p.ends_on AND b.to_date>p.starts_on;
 SELECT EXISTS(SELECT 1 FROM accounting.bas_tax_events WHERE company_id=c AND attribution_date>=p.starts_on AND attribution_date<p.ends_on AND gst_amount<>0)OR EXISTS(SELECT 1 FROM accounting.bas_turnover(p.starts_on,p.ends_on)WHERE gross_amount<>0)OR EXISTS(SELECT 1 FROM purchase.bill_lines l JOIN purchase.bills b ON b.company_id=l.company_id AND b.id=l.bill_id JOIN platform.documents d ON d.company_id=b.company_id AND d.id=b.id WHERE l.company_id=c AND((b.invoice_date>=p.starts_on AND b.invoice_date<p.ends_on)OR(d.business_date>=p.starts_on AND d.business_date<p.ends_on))AND(l.snapshot->>'gstRegistered')::boolean) INTO activity;
 required:=required OR activity OR covered>0;
 IF p_bas_na THEN IF activity OR covered>0 THEN issues:=issues||jsonb_build_array('BAS_NOT_APPLICABLE_CONTRADICTS_SOURCES');END IF;ELSE IF required AND covered<>p.ends_on-p.starts_on THEN issues:=issues||jsonb_build_array('BAS_COVERAGE_MISSING');END IF;END IF;
 IF bad>0 THEN issues:=issues||jsonb_build_array('ENDED_BAS_PERIOD_NOT_FINALIZED');END IF;
 IF EXISTS(SELECT 1 FROM accounting.bas_effective_periods b JOIN accounting.bas_period_controls k ON k.company_id=b.company_id AND k.id=b.id JOIN accounting.bas_snapshots bs ON bs.company_id=k.company_id AND bs.id=k.current_snapshot_id WHERE b.company_id=c AND b.from_date<p.ends_on AND b.to_date>p.starts_on AND k.state IN('FINALIZED','LODGED')AND accounting.bas_financial_hash(accounting.bas_report(b.from_date,b.to_date,b.reporting_method,b.calculation_method))<>bs.financial_hash)THEN issues:=issues||jsonb_build_array('BAS_SNAPSHOT_DRIFT');END IF;
 IF EXISTS(SELECT 1 FROM incentives.runs r WHERE r.company_id=c AND r.posting_date>=p.starts_on AND r.posting_date<p.ends_on AND r.state='DRAFT'AND EXISTS(SELECT 1 FROM jsonb_array_elements(r.plan->'lines')e WHERE(e->>'delta')::numeric<>0))THEN issues:=issues||jsonb_build_array('INCENTIVE_ACCRUAL_PENDING');END IF;
 RETURN jsonb_build_object('companyId',c,'periodId',p.id,'fiscalYearId',p.fiscal_year_id,'from',p.starts_on,'to',p.ends_on,'state',p.state,'version',p.version,'legacyUncertified',p.state='CLOSED'AND p.current_close_snapshot_id IS NULL,'basNotApplicableConfirmed',p_bas_na,'basRequired',required,'basPeriods',bas,'status',CASE WHEN jsonb_array_length(issues)=0 THEN'READY'ELSE'BLOCKED'END,'issues',issues,'currentMismatches',live,'financial',f,'yearEndBridge',accounting.year_closing_bridge(p.ends_on),'snapshotAt',statement_timestamp());END $$;

CREATE FUNCTION incentives.offset_claims(p_id uuid,p_positive uuid,p_negative uuid,p_amount numeric,p_date date,p_reference text,p_reason text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE pos incentives.claims;neg incentives.claims;pa uuid;na uuid;plan jsonb;cl incentives.claims;BEGIN
 PERFORM incentives.require_access('incentives.settle');PERFORM incentives.lock_company();SELECT*INTO pos FROM incentives.claims WHERE company_id=core.current_company()AND id=p_positive;SELECT*INTO neg FROM incentives.claims WHERE company_id=core.current_company()AND id=p_negative;
 IF pos.id IS NULL OR neg.id IS NULL OR pos.kind<>neg.kind OR pos.beneficiary_id<>neg.beneficiary_id THEN RAISE EXCEPTION 'Same beneficiary and incentive kind required' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM platform.documents WHERE company_id=pos.company_id AND id IN(SELECT order_id FROM sales.invoices WHERE company_id=pos.company_id AND id IN(pos.invoice_id,neg.invoice_id))ORDER BY id FOR UPDATE;PERFORM incentives.require_open(p_date);PERFORM incentives.require_access('incentives.settle');
 IF p_date<(SELECT max(posting_date)FROM incentives.accruals WHERE company_id=pos.company_id AND claim_id IN(pos.id,neg.id))OR p_amount IS NULL OR p_amount<=0 OR p_amount<>round(p_amount,2)OR p_amount>incentives.claim_balance(pos.id)OR p_amount>-incentives.claim_balance(neg.id)OR coalesce(length(btrim(p_reference)),0)NOT BETWEEN 1 AND 180 OR coalesce(length(btrim(p_reason)),0)NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Offset exceeds positive/negative balance or lacks evidence' USING ERRCODE='HR422';END IF;
 FOR cl IN SELECT*FROM incentives.claims WHERE company_id=pos.company_id AND id IN(pos.id,neg.id)LOOP plan:=incentives.build_plan(cl.program_id,cl.origin_period_id,incentives.today(),ARRAY[cl.invoice_id]);IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(plan->'lines')e WHERE(e->>'invoiceId')::uuid=cl.invoice_id AND(e->>'delta')::numeric=0)THEN RAISE EXCEPTION 'Approve current source adjustments first' USING ERRCODE='HR409';END IF;END LOOP;
 SELECT liability_account_id INTO pa FROM incentives.policies WHERE company_id=pos.company_id AND id=pos.policy_id;SELECT liability_account_id INTO na FROM incentives.policies WHERE company_id=neg.company_id AND id=neg.policy_id;
 INSERT INTO platform.documents(company_id,id,document_type,business_date,state,created_by)VALUES(pos.company_id,p_id,'INCENTIVE_SETTLEMENT',p_date,'CONFIRMED',core.current_actor());INSERT INTO incentives.settlements(company_id,id,program_id,mode,posting_date,reference,reason,evidence,net,tax,created_by)VALUES(pos.company_id,p_id,pos.program_id,'OFFSET',p_date,p_reference,p_reason,'NET OFFSET ONLY; GST reviewed separately',0,0,core.current_actor());INSERT INTO incentives.settlement_lines VALUES(pos.company_id,p_id,pos.id,p_amount),(pos.company_id,p_id,neg.id,-p_amount);
 IF pa<>na THEN PERFORM accounting.post_journal(p_id,1,'INCENTIVE_SETTLEMENT',p_date,'Offset incentive recovery against approved entitlement',jsonb_build_array(jsonb_build_object('accountId',pa,'debit',p_amount),jsonb_build_object('accountId',na,'credit',p_amount)));END IF;UPDATE platform.documents SET state='POSTED'WHERE company_id=pos.company_id AND id=p_id;RETURN jsonb_build_object('id',p_id,'mode','OFFSET','amount',p_amount,'status','OFFSET');END$$;
CREATE FUNCTION incentives.check_source_journal()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE doc uuid;kind text;BEGIN
 SELECT b.source_document_id,b.posting_kind INTO doc,kind FROM accounting.journal_entries j JOIN accounting.posting_batches b ON b.company_id=j.company_id AND b.id=j.posting_batch_id WHERE j.company_id=NEW.company_id AND j.id=NEW.journal_entry_id;
 IF EXISTS(SELECT 1 FROM incentives.runs WHERE company_id=NEW.company_id AND id=doc)OR EXISTS(SELECT 1 FROM incentives.settlements WHERE company_id=NEW.company_id AND id=doc)THEN
 IF(SELECT count(*)FROM accounting.posting_batches WHERE company_id=NEW.company_id AND source_document_id=doc)>1 OR EXISTS(WITH expected AS(
 SELECT(e->>'accountId')::uuid account,coalesce((e->>'debit')::numeric,0)-coalesce((e->>'credit')::numeric,0)amount FROM jsonb_array_elements(incentives.run_postings(doc))e
 UNION ALL SELECT p.liability_account_id,l.amount FROM incentives.settlement_lines l JOIN incentives.claims c ON c.company_id=l.company_id AND c.id=l.claim_id JOIN incentives.policies p ON p.company_id=c.company_id AND p.id=c.policy_id WHERE l.company_id=NEW.company_id AND l.settlement_id=doc
 UNION ALL SELECT CASE WHEN s.mode='CLEARING'THEN(p.config->>'clearingAccountId')::uuid ELSE p.expense_account_id END,-l.amount FROM incentives.settlement_lines l JOIN incentives.settlements s ON s.company_id=l.company_id AND s.id=l.settlement_id JOIN incentives.claims c ON c.company_id=l.company_id AND c.id=l.claim_id JOIN incentives.policies p ON p.company_id=c.company_id AND p.id=c.policy_id WHERE l.company_id=NEW.company_id AND l.settlement_id=doc AND s.mode<>'OFFSET'),wanted AS(SELECT account,sum(amount)n FROM expected GROUP BY account),actual AS(SELECT l.account_id account,sum(l.debit-l.credit)n FROM accounting.journal_lines l JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id JOIN accounting.posting_batches b ON b.company_id=j.company_id AND b.id=j.posting_batch_id WHERE l.company_id=NEW.company_id AND b.source_document_id=doc GROUP BY l.account_id)SELECT 1 FROM wanted w FULL JOIN actual a USING(account)WHERE coalesce(w.n,0)<>coalesce(a.n,0))OR kind NOT IN('INCENTIVE_ACCRUAL','INCENTIVE_SETTLEMENT')THEN RAISE EXCEPTION 'Incentive journal differs from approved source' USING ERRCODE='23514';END IF;END IF;RETURN NULL;END$$;
CREATE CONSTRAINT TRIGGER incentive_source AFTER INSERT ON accounting.journal_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION incentives.check_source_journal();
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA incentives FROM PUBLIC;GRANT EXECUTE ON FUNCTION incentives.offset_claims(uuid,uuid,uuid,numeric,date,text,text)TO htt_app;

CREATE FUNCTION incentives.require_settlement(p_claim uuid)RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE cl incentives.claims;v incentives.policies;BEGIN PERFORM incentives.require_access('incentives.settle');SELECT*INTO cl FROM incentives.claims WHERE company_id=core.current_company()AND id=p_claim;IF NOT FOUND THEN RAISE EXCEPTION 'Claim unavailable' USING ERRCODE='HT404';END IF;SELECT*INTO v FROM incentives.policies WHERE company_id=cl.company_id AND id=cl.policy_id;
 IF v.config->>'settlementMode'='CUSTOMER_CREDIT'THEN PERFORM sales.require_customer_access('sales.credits.adjust',(SELECT customer_id FROM sales.invoices WHERE company_id=cl.company_id AND id=cl.invoice_id));PERFORM sales.require_customer_access('sales.credits.write',(SELECT customer_id FROM sales.invoices WHERE company_id=cl.company_id AND id=cl.invoice_id));ELSIF v.config->>'settlementMode'='SUPPLIER_BILL'THEN PERFORM purchase.require_access('purchase.expense_bills.post');PERFORM purchase.require_access('purchase.expense_credits.post');END IF;END$$;
CREATE FUNCTION incentives.guard_account_kind()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF ROW(NEW.kind,NEW.control_kind)IS DISTINCT FROM ROW(OLD.kind,OLD.control_kind)AND EXISTS(SELECT 1 FROM incentives.liability_accounts WHERE company_id=OLD.company_id AND account_id=OLD.id)THEN RAISE EXCEPTION 'Reserved incentive liability classification is immutable' USING ERRCODE='23514';END IF;RETURN NEW;END$$;
CREATE TRIGGER incentive_account_kind BEFORE UPDATE ON accounting.accounts FOR EACH ROW EXECUTE FUNCTION incentives.guard_account_kind();
CREATE FUNCTION incentives.list_programs(p_offset int,p_size int)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM incentives.require_access('incentives.read');IF p_offset<0 OR p_size NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid page' USING ERRCODE='HR422';END IF;RETURN jsonb_build_object('totalCount',(SELECT count(*)FROM incentives.programs WHERE company_id=core.current_company()),'items',(SELECT coalesce(jsonb_agg(to_jsonb(p)ORDER BY p.id),'[]')FROM(SELECT*FROM incentives.programs WHERE company_id=core.current_company()ORDER BY id OFFSET p_offset LIMIT p_size)p));END$$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA incentives FROM PUBLIC;GRANT EXECUTE ON FUNCTION incentives.require_settlement(uuid),incentives.list_programs(int,int)TO htt_app;
CREATE FUNCTION incentives.write_lock()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM accounting.bas_lock(coalesce(NEW.company_id,OLD.company_id),false);RETURN coalesce(NEW,OLD);END$$;REVOKE ALL ON FUNCTION incentives.write_lock()FROM PUBLIC;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['runs','accruals','settlements','settlement_lines']LOOP EXECUTE format('CREATE TRIGGER bas_lock BEFORE INSERT OR UPDATE OR DELETE ON incentives.%I FOR EACH ROW EXECUTE FUNCTION incentives.write_lock()',t);END LOOP;END$$;
-- Bounded finance read model; internal review snapshots retain the complete approved ledger.
CREATE FUNCTION incentives.ledger_page(p_offset int,p_size int)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 PERFORM incentives.require_access('incentives.read');IF p_offset IS NULL OR p_offset<0 OR p_size IS NULL OR p_size NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Valid page required' USING ERRCODE='HR422';END IF;
 RETURN jsonb_build_object('snapshotAt',statement_timestamp(),'page',p_offset/p_size+1,'pageSize',p_size,'claimCount',(SELECT count(*)FROM incentives.claims WHERE company_id=core.current_company()),'settlementCount',(SELECT count(*)FROM incentives.settlements WHERE company_id=core.current_company()),'claims',(SELECT coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('accrued',incentives.claim_accrued(c.id),'balance',incentives.claim_balance(c.id))ORDER BY c.id),'[]')FROM(SELECT*FROM incentives.claims WHERE company_id=core.current_company()ORDER BY id OFFSET p_offset LIMIT p_size)c),'settlements',(SELECT coalesce(jsonb_agg(to_jsonb(s)ORDER BY s.id),'[]')FROM(SELECT*FROM incentives.settlements WHERE company_id=core.current_company()ORDER BY id OFFSET p_offset LIMIT p_size)s));END$$;
CREATE OR REPLACE FUNCTION incentives.personal()RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 PERFORM incentives.require_access('incentives.self.read');RETURN(WITH visible AS(SELECT p.*FROM incentives.programs p WHERE company_id=core.current_company()AND((p.kind='COMMISSION'AND p.user_id=core.current_actor())OR(p.kind='REBATE'AND crm.mobile_customer_visible(p.customer_id)AND EXISTS(SELECT 1 FROM incentives.display_grants g WHERE g.company_id=p.company_id AND g.program_id=p.id AND g.user_id=core.current_actor()AND g.active)))),totals AS(SELECT p.id,p.kind,p.name,count(c.id)n,coalesce(sum(incentives.claim_accrued(c.id)),0)approved,coalesce(sum(incentives.claim_balance(c.id)),0)balance,bool_or(incentives.claim_balance(c.id)>0)positive,bool_or(incentives.claim_balance(c.id)<0)negative FROM visible p LEFT JOIN incentives.claims c ON c.company_id=p.company_id AND c.program_id=p.id GROUP BY p.id,p.kind,p.name)
 SELECT coalesce(jsonb_agg(jsonb_build_object('programId',id,'kind',kind,'name',name,'approvedNet',approved,'balance',balance,'transferredNet',approved-balance,'state',CASE WHEN n=0 THEN'NO_ACCRUAL'WHEN positive AND negative THEN'ADJUSTMENT_REQUIRED'WHEN negative THEN'RECOVERY_DUE'WHEN positive THEN'APPROVED_BALANCE'ELSE'CLEARED'END)ORDER BY id),'[]')FROM totals);END$$;
REVOKE ALL ON FUNCTION incentives.ledger_page(int,int)FROM PUBLIC;REVOKE EXECUTE ON FUNCTION incentives.ledger()FROM htt_app;GRANT EXECUTE ON FUNCTION incentives.ledger_page(int,int)TO htt_app;
CREATE INDEX incentive_settlement_claim_lookup ON incentives.settlement_lines(company_id,claim_id);
CREATE INDEX incentive_settlement_source_lookup ON incentives.settlements(company_id,underlying_document_id)WHERE underlying_document_id IS NOT NULL;
